import React, { useState } from 'react';
import axios from 'axios';

const styles = {
  section: {
    padding: '48px 24px',
    backgroundColor: '#f7fafc',
  },
  container: {
    maxWidth: '1200px',
    margin: '0 auto',
  },
  h2: {
    fontSize: '2rem',
    fontWeight: 'bold',
    color: '#2d3748',
    marginBottom: '24px',
  },
  form: {
    maxWidth: '800px',
  },
  formGroup: {
    marginBottom: '24px',
  },
  label: {
    display: 'block',
    fontSize: '1.1rem',
    fontWeight: '500',
    color: '#4a5568',
    marginBottom: '8px',
  },
  input: {
    width: '100%',
    padding: '12px',
    fontSize: '1rem',
    border: '1px solid #cbd5e0',
    borderRadius: '6px',
    boxSizing: 'border-box',
  },
  button: {
    width: '100%',
    backgroundColor: '#00796b',
    color: 'white',
    fontWeight: 'bold',
    fontSize: '1.1rem',
    padding: '14px 24px',
    borderRadius: '8px',
    border: 'none',
    cursor: 'pointer',
  },
};

const AppointmentForm = () => {
  const [formData, setFormData] = useState({ name: '', phone: '', date: '', message: '' });

  const handleChange = (e) => setFormData({ ...formData, [e.target.name]: e.target.value });

  const handleSubmit = async (e) => {
    e.preventDefault();
    try {
      await axios.post("http://localhost:5000/api/appointments", formData);
      alert("Appointment submitted successfully!");
      setFormData({ name: '', phone: '', date: '', message: '' });
    } catch (err) {
      console.error(err);
      alert("Failed to submit appointment.");
    }
  };

  return (
    <section id="contact" style={styles.section}>
      <div style={styles.container}>
        <h2 style={styles.h2}>Book an Appointment</h2>
        <form onSubmit={handleSubmit} style={styles.form}>
          <div style={styles.formGroup}>
            <label htmlFor="name" style={styles.label}>Your Name</label>
            <input type="text" name="name" id="name" required style={styles.input} value={formData.name} onChange={handleChange} />
          </div>
          <div style={styles.formGroup}>
            <label htmlFor="phone" style={styles.label}>Phone Number</label>
            <input type="tel" name="phone" id="phone" required style={styles.input} value={formData.phone} onChange={handleChange} />
          </div>
          <div style={styles.formGroup}>
            <label htmlFor="date" style={styles.label}>Preferred Date</label>
            <input type="date" name="date" id="date" required style={styles.input} value={formData.date} onChange={handleChange} />
          </div>
          <div style={styles.formGroup}>
            <label htmlFor="message" style={styles.label}>Reason for Appointment</label>
            <textarea name="message" id="message" rows="4" required style={styles.input} value={formData.message} onChange={handleChange}></textarea>
          </div>
          <button type="submit" style={styles.button}>Submit Appointment</button>
        </form>
      </div>
    </section>
  );
};

export default AppointmentForm;
